export type TerrainReportKey = keyof typeof TERRAIN_REPORT_TEXT;

const COLUMN: Readonly<Record<ExportLanguage, number>> = { en: 0, es: 1, pt: 2, fr: 3, de: 4 };

/** A row's template in a language. */
export function terrainReportTemplate(lang: ExportLanguage, key: TerrainReportKey): string {
  return TERRAIN_REPORT_TEXT[key][COLUMN[lang]]!;
}
